package meow.nyx.quackjs

import kotlin.time.TimeSource

// Explicit konanc -entry only; never registered as a default test. See the lane-31 report.
public fun nativePerformanceLane31() {
    val source = realPlayerSlice
    val hints = PlayerHints("Su(11,3932,INPUT)", "cg", 20724)
    // Same independently checked outputs as RealPlayerTest, not generated by this workload.
    val vectors = listOf(
        Triple("KdrqFlzJXl9EcCwlmEy", "yEmlwCcE9lqXz", "FMSB9mkLYExhqEndTt"),
        Triple("0123456789abcdefghijklmno", "3nml0jihgfedcba9876", "dAnUtb3-oHMvmOcWU7RC1xmM"),
        Triple("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-", "-_9876543210ZYXWVUaSRQPONMLKJIHGFEDCBAzdxwvutsrqponmlyjihg", "m4bL7DwMbqhzWG2-rHWl6T47XB9Bfe86z66bci1Z3aWa1uyzwUy_SUvQCufD3Yv"),
        Triple("a/b=?%\u2603\ud83d\ude00", "\ude00\ud83d=", "ZAI3afmu"),
        Triple("a", "", ""),
        Triple("", "", ""),
    )
    val expected = vectors.flatMap { listOf(it.second, it.third) }
    fun solve(program: PlayerProgram, repeats: Int): List<String> = buildList(vectors.size * 2 * repeats) {
        repeat(repeats) {
            for ((input, _, _) in vectors) {
                add(program.decipherSignature(input))
                add(program.transformN(input))
            }
        }
    }

    val program = PlayerProgram.compile(source, hints)
    check(program.signatureTimestamp == 20724)
    check(solve(program, 1) == expected) { "Extracted-player preflight failed" }
    println("fixture=eb27e5fd extracted dependencies only; not the full player or a QuickJS comparison")
    println("warmups=3 samples=11; monotonic timing; no forced GC or timing assertions")
    println("sourceUtf16=${source.length} vectorInputUtf16=${vectors.map { it.first.length }}")

    val first = vectors.first().first
    measureLane31("cold compile+first signature+n", expected.take(2)) {
        val cold = PlayerProgram.compile(source, hints)
        listOf(cold.decipherSignature(first), cold.transformN(first))
    }
    val repeats = 16
    val expectedBatch = List(repeats) { expected }.flatten()
    measureLane31("warm batch transforms=${expectedBatch.size}", expectedBatch) { solve(program, repeats) }
}

private fun measureLane31(label: String, expected: List<String>, solve: () -> List<String>) {
    val times = LongArray(11)
    repeat(3 + times.size) { sample ->
        val start = TimeSource.Monotonic.markNow()
        val actual = solve()
        val elapsed = start.elapsedNow().inWholeNanoseconds
        check(actual == expected) { "$label sample=$sample output mismatch; discard this run" }
        if (sample >= 3) times[sample - 3] = elapsed
    }
    println("$label medianMs=${times.sorted()[times.size / 2] / 1_000_000.0} samplesNs=${times.joinToString(",")}")
}
